import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

public class BindingAssignerTest extends QueryOptimizerTest {

	@Override
	public BindingAssignerOptimizer getOptimizer() {
		return new BindingAssignerOptimizer();
	}

	@Test
	void tupleFunctionResultConstraintsUseTheirProvenCallInput() {
		var valueFactory = SimpleValueFactory.getInstance();
		var parameter = valueFactory.createLiteral("alpha");
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("value", parameter);
		TupleFunctionCall call = repeatedResultCall();
		getOptimizer().optimize(new QueryRoot(call), null, bindings);
		assertThat(call.getResultVars()).allSatisfy(variable -> {
			assertThat(variable.getValue()).isEqualTo(parameter);
			assertThat(variable.hasApiInputOrigin()).isTrue();
		});

		call = repeatedResultCall();
		var local = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(valueFactory.createLiteral("bravo")), "value"));
		getOptimizer().optimize(new QueryRoot(new Join(local, call)), null, bindings);
		assertThat(call.getResultVars()).allSatisfy(variable -> assertThat(variable.hasValue()).isFalse());

		TupleFunctionCall opaque = new TupleFunctionCall() {
		};
		opaque.addResultVar(new Var("value"));
		getOptimizer().optimize(new QueryRoot(opaque), null, bindings);
		assertThat(opaque.getResultVars()).singleElement()
				.satisfies(variable -> assertThat(variable.hasValue()).isFalse());
	}

	private static TupleFunctionCall repeatedResultCall() {
		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI("urn:test:result-constraints");
		call.addResultVars(new Var("value"), new Var("value"));
		return call;
	}

}
